<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=in_array($_POST['status']??'', ['pending','published','hidden','sold'],true)?$_POST['status']:'pending';db()->prepare('UPDATE products SET status=?,featured=? WHERE id=?')->execute([$status,isset($_POST['featured'])?1:0,$id]);audit_log('product.moderated','product',$id,['status'=>$status,'featured'=>isset($_POST['featured'])]);flash('success','Publicación actualizada.');redirect('../admin/products.php');}
$q=trim((string)($_GET['q']??''));$status=in_array($_GET['status']??'', ['pending','published','hidden','sold'],true)?$_GET['status']:'';$page=max(1,(int)($_GET['page']??1));$perPage=30;$where=[];$args=[];
if($q!==''){$where[]='(pr.title LIKE ? OR p.display_name LIKE ? OR c.name LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);}if($status!==''){$where[]='pr.status=?';$args[]=$status;}$ws=$where?' WHERE '.implode(' AND ',$where):'';
$ct=db()->prepare("SELECT COUNT(*) FROM products pr JOIN profiles p ON p.user_id=pr.user_id JOIN categories c ON c.id=pr.category_id{$ws}");$ct->execute($args);$total=(int)$ct->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$st=db()->prepare("SELECT pr.*,p.display_name,c.name category FROM products pr JOIN profiles p ON p.user_id=pr.user_id JOIN categories c ON c.id=pr.category_id{$ws} ORDER BY pr.created_at DESC LIMIT {$perPage} OFFSET {$offset}");$st->execute($args);$items=$st->fetchAll();
$adminPage='products';$adminTitle='Moderación de publicaciones';$adminSubtitle='Aprobar, destacar u ocultar artículos y servicios de la vitrina';require __DIR__.'/partials/header.php';?>
<section class="panel-card mt-0"><div class="panel-head"><div><h2>📦 Catálogo enviado</h2><p><?=$total?> artículos encontrados · página <?=$page?> de <?=$pages?></p></div></div><form method="get" class="admin-filterbar admin-filterbar-pro"><input class="admin-search" name="q" value="<?=e($q)?>" placeholder="Buscar artículo, vendedor o categoría..."><select name="status"><option value="">Todos los estados</option><?php foreach(['pending','published','hidden','sold'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="admin-btn">🔎 Filtrar</button><a class="admin-btn secondary" href="products.php">Limpiar</a></form><div class="admin-table-wrap mt-20"><table class="admin-table"><thead><tr><th>Artículo</th><th>Vendedor</th><th>Precio</th><th>Visitas</th><th>Estado</th><th>Moderación</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><a target="_blank" href="<?=url('product.php?id='.$i['id'])?>"><b><?=e($i['title'])?></b></a><small><?=e($i['category'])?> · <?=e(date('d/m/Y',strtotime($i['created_at'])))?></small></td><td><?=e($i['display_name'])?></td><td><b><?=money_clp($i['price_clp'])?></b></td><td><?=$i['views']?></td><td><span class="status <?=e($i['status'])?>"><?=e($i['status'])?></span><?php if($i['featured']):?><small>🔥 Destacado</small><?php endif;?></td><td><form method="post" class="inline-admin-form"><input type="hidden" name="id" value="<?=$i['id']?>"><?=csrf_field()?><select name="status"><?php foreach(['pending','published','hidden','sold'] as $s):?><option <?=$i['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><label style="display:flex;align-items:center;gap:5px"><input style="width:auto" type="checkbox" name="featured" <?=$i['featured']?'checked':''?>> ⭐</label><button class="admin-btn small">Guardar</button></form></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="6"><div class="empty-admin">No se encontraron publicaciones.</div></td></tr><?php endif;?></tbody></table></div><?=admin_pagination($page,$pages,$_GET)?></section>
<?php require __DIR__.'/partials/footer.php';?>
